CustomField.formula:
IF( ISPICKVAL(Type__c , 'QS'), /* Type이 'QS'일 때:QS */ 'QS', IF(
Excess__c = 0, /* Excess가 0일 때: LOL xs OPDs */ IF(ABS(LOL__c) >= 1000000000000, TEXT(LOL__c / 1000000000000) & "tr", IF(ABS(LOL__c) >= 1000000000, TEXT(LOL__c / 1000000000) & "bn", IF(ABS(LOL__c) >= 1000000, TEXT(LOL__c / 1000000) & "M", TEXT(LOL__c)))) & " xs OPDs",
/* Excess가 0이 아닐 때: LOL xs Excess xs OPDs */ IF(ABS(LOL__c) >= 1000000000000, TEXT(LOL__c / 1000000000000) & "tr", IF(ABS(LOL__c) >= 1000000000, TEXT(LOL__c / 1000000000) & "bn", IF(ABS(LOL__c) >= 1000000, TEXT(LOL__c / 1000000) & "M", TEXT(LOL__c)))) & " xs " & IF(ABS(Excess__c) >= 1000000000000, TEXT(Excess__c / 1000000000000) & "tr", IF(ABS(Excess__c) >= 1000000000, TEXT(Excess__c / 1000000000) & "bn", IF(ABS(Excess__c) >= 1000000, TEXT(Excess__c / 1000000) & "M", TEXT(Excess__c)))) & " xs OPDs" ) )
